Single-Page App (SPA).diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

title Component diagram for the Single-Page App (SPA) container

Container_Boundary(spa, "Single-Page App (SPA)") {
    Component(router_view_controller, "Router & View Controller", "React Router", "Manages client-side routing, view rendering, and navigation across different pages of the bookstore.")
    Component(global_state_store, "Global State Store", "Redux Toolkit", "Manages global application state, user sessions, shopping cart data, and caching for fast rendering.")
    Component(api_client_service, "API Client Service", "Axios / Fetch API", "Handles HTTP requests and communication with the backend API Gateway.")
}

Rel(router_view_controller, global_state_store, "Reads and updates application state")
Rel(router_view_controller, api_client_service, "Triggers API calls on user interaction")
Rel(api_client_service, global_state_store, "Stores fetched data")

@enduml

API Gateway.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(api_gateway, "API Gateway") {
    Component(RoutingDispatcherComponent, "Routing & Dispatcher Component", "AWS API Gateway Routing", "Dispatches sanitized payloads to downstream services.")
    Component(AuthenticationAuthorizationComponent, "Authentication & Authorization Component", "AWS API Gateway Auth", "Validates tokens and forwards identity context.")
    Component(RateLimitingThrottlingComponent, "Rate Limiting & Throttling Component", "AWS API Gateway Throttling", "Manages edge rate-limiting.")
    Component(RequestTransformationValidationComponent, "Request Transformation & Validation Component", "AWS API Gateway Validation", "Validates and transforms incoming requests.")
}

Rel(AuthenticationAuthorizationComponent, RequestTransformationValidationComponent, "Forwards identity context", "Internal")
Rel(RequestTransformationValidationComponent, RoutingDispatcherComponent, "Dispatches sanitized payloads", "Internal")

@enduml

Amazon RDS (PostgreSQL).diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(amazon_rds_postgresql, "Amazon RDS (PostgreSQL)") {
    Component(Connection Pooler, "Connection Pooler", "PgBouncer / RDS Proxy", "Manages and pools database connections to mitigate exhaustion under high concurrency.")
    Component(Relational Schema, "Relational Schema", "PostgreSQL", "ACID-compliant relational data storage for core transactional data.")
    Component(Read Replica, "Read Replica", "PostgreSQL Read Replica", "Handles read-heavy workloads through asynchronous replication.")
    Component(Audit Component, "Audit Component", "pgAudit", "Provides detailed session and object audit logging for GDPR/CCPA compliance.")
    Component(PITR Component, "PITR Component", "AWS Automated Backups", "Enables Point-In-Time Recovery for data protection and disaster recovery.")
}

Rel(Connection Pooler, Relational Schema, "TCP Local / Unix Domain Sockets")
Rel(Relational Schema, Read Replica, "Asynchronous replication")

@enduml

Amazon OpenSearch.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(amazon_opensearch, "Amazon OpenSearch") {
    Component(CatalogSearchIndex, "Catalog Search Index", "Amazon OpenSearch Managed Index", "Stores and indexes book catalog data for fast retrieval and full-text search.")
    Component(OpenSearchRESTAPIEngine, "OpenSearch REST API Engine", "OpenSearch REST API", "Handles incoming search and synchronization queries from the Catalog Service.")
    Component(IndexManagementIngestionService, "Index Management & Ingestion Service", "OpenSearch Ingestion Service", "Manages data ingestion pipelines and index lifecycles.")
    Component(SearchAnalyticsSuggestionsEngine, "Search Analytics & Suggestions Engine", "OpenSearch Analytics Engine", "Powers search auto-complete suggestions and search analytics for the platform.")
}

Rel(OpenSearchRESTAPIEngine, CatalogSearchIndex, "Queries and synchronizes product data")
Rel(SearchAnalyticsSuggestionsEngine, CatalogSearchIndex, "Fetches indexing data for auto-complete suggestions")

@enduml

AWS EventBridge & SQS.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(aws_eventbridge_sqs, "AWS EventBridge & SQS") {
    Component(AWS_EventBridge_Event_Bus, "AWS EventBridge Event Bus", "AWS EventBridge", "Publishes and routes domain events based on pattern rules.")
    Component(Amazon_SQS_Queues, "Amazon SQS Queues", "Amazon SQS", "Queues messages routed from EventBridge for asynchronous processing.")
    Component(SQS_Dead_Letter_Queues_DLQs_, "SQS Dead Letter Queues (DLQs)", "Amazon SQS DLQ", "Captures failed messages for error handling and debugging.")
}

Rel(AWS_EventBridge_Event_Bus, Amazon_SQS_Queues, "Routes messages based on pattern rules", "SQS Queue Policy / AWS internal API")
Rel(Amazon_SQS_Queues, SQS_Dead_Letter_Queues_DLQs_, "Forwards failed messages after max receive count is exceeded")

@enduml
